<template>
  <main><h1>编辑器交互验收</h1><p>真实组件、隔离草稿与来源，不连接模型或账户。</p><section ref="anchor" class="fixture-composer"><ComposerEditor ref="field" v-model="document" chat-id="chat-a" @attach="openMenu" @submit="submits++" @notify="notices.push($event)" /><footer><button type="button" aria-label="附加" title="附加文件、网页或会话，也可输入 /" @pointerdown.prevent="field?.saveSelection()" @click="openMenu"><AppIcon icon="paperclip" /></button><span>Enter 发送 · Shift Enter 换行</span></footer></section><MessageQueue v-if="queueOpen" chat-id="chat-a" :entries="queueEntries" :busy="false" :paused="false" :max-chars="16000" /><ComposerAttachmentMenu ref="menu" @select="selected" @creator="creator=$event" @closed="menuClosed" /><ComposerSourcePicker ref="picker" chat-id="chat-a" @insert="insertSources" /><p v-if="notices.length" role="status">{{ notices.at(-1) }}</p></main>
</template>
<script setup lang="ts">
import {nextTick,ref} from 'vue'
import MessageQueue from '../../src/components/MessageQueue.vue'
import type {QueuedMessage} from '../../shared/types'
import ComposerEditor from '../../src/components/ComposerEditor.vue'
import ComposerAttachmentMenu from '../../src/components/ComposerAttachmentMenu.vue'
import ComposerSourcePicker,{type ComposerSourceInsert} from '../../src/components/ComposerSourcePicker.vue'
import AppIcon from '../../src/components/icons/AppIcon.vue'
import {compileComposerDocument,createComposerDocument,type ComposerNode} from '../../shared/composer-document'
const queueOpen=ref(false),queueEntries=ref<QueuedMessage[]>([])
const document=ref(createComposerDocument('chat-a','请检查这份需求并总结。')),field=ref<InstanceType<typeof ComposerEditor>>(),menu=ref<InstanceType<typeof ComposerAttachmentMenu>>(),picker=ref<InstanceType<typeof ComposerSourcePicker>>(),anchor=ref<HTMLElement>(),submits=ref(0),notices=ref<string[]>([]),creator=ref(''),selectedSource=ref(''),apiCalls:string[]=[]
;(window as any).navora={app:{platform:"web"},skills:{list:async()=>{apiCalls.push('skills.list');return [{id:'example-skill',name:'说明技能',description:'校对资料',updatedAt:1}]},get:async()=>{apiCalls.push('skills.get');return {id:'example-skill',name:'说明技能',description:'校对资料',body:'这是技能正文，请按本技能执行。',updatedAt:1}},setEnabled:async()=>{throw Error('A material attachment must never enable a skill')}},plugins:{list:async()=>{apiCalls.push('plugins.list');return [{id:'example-plugin',name:'说明插件',description:'资料工具',version:'1',tools:['search_docs'],hasReadme:true}]},readReadme:async()=>{apiCalls.push('plugins.readReadme');return {ok:true,markdown:'# 插件说明\n请在授权范围中使用。'}},setEnabled:async()=>{throw Error('A material attachment must never enable a plugin')}}}
function openMenu(){if(anchor.value)menu.value?.show(anchor.value)}
function selected(source:string){field.value?.consumeAttachmentTrigger();selectedSource.value=source}
function menuClosed(committed:boolean){if(!committed)field.value?.cancelAttachmentTrigger()}
function insertSources(items:ComposerSourceInsert[]){for(const item of items)field.value?.insertContext(item.block,item.text)}
;(window as any).fixture={
  async reset(text='请检查这份需求并总结。'){menu.value?.hide();document.value=createComposerDocument('chat-a',text);submits.value=0;notices.value=[];await nextTick();await nextTick();field.value?.focus();await new Promise(resolve=>requestAnimationFrame(()=>requestAnimationFrame(resolve)))},
  get document(){return JSON.parse(JSON.stringify(document.value))},get compiled(){return compileComposerDocument(document.value)},get submits(){return submits.value},get notices(){return notices.value},get source(){return selectedSource.value},get creator(){return creator.value},
  async set(content:ComposerNode[]){document.value={...createComposerDocument('chat-a'),content};await nextTick();await nextTick();field.value?.focus()},
  openMenu,selectAll(){field.value?.select()},bookmark(){return field.value?.saveSelection()},selection(){return field.value?.getTextSelection()},undo(){return field.value?.executeCommand('undo')},redo(){return field.value?.executeCommand('redo')},
  openPicker(source:string){field.value?.saveSelection();return picker.value?.show(source)},get apiCalls(){return [...apiCalls]},
  async openQueue(excerpt=false){queueOpen.value=false;await nextTick();const doc=createComposerDocument('chat-a','队列正文');if(excerpt)doc.content=[{type:'contextBlock',attrs:{block:{id:crypto.randomUUID(),label:'队列摘录',mode:'excerpt',status:'ready',source:{kind:'text',identity:'manual:queue',chatId:'chat-a'}}},content:[{type:'paragraph',content:[{type:'text',text:'可编辑摘录正文'}]}]},{type:'paragraph',content:[{type:'text',text:'摘录之后'}]}];queueEntries.value=[{id:crypto.randomUUID(),content:compileComposerDocument(doc).content,document:doc,createdAt:Date.now()} as QueuedMessage];queueOpen.value=true;await nextTick()},
  async selectQueueExcerpt(){const root=window.document.querySelector<HTMLElement>('.message-queue .composer-richtext')!;root.querySelector<HTMLButtonElement>('.composer-context-inline>button')!.click();await nextTick();const text=root.querySelector('.composer-context-content p')!.firstChild!,range=window.document.createRange();root.focus();range.setStart(text,2);range.setEnd(text,3);const selected=window.getSelection()!;selected.removeAllRanges();selected.addRange(range);window.document.dispatchEvent(new Event('selectionchange'))},
  unsupported(){document.value={...createComposerDocument('chat-a'),schemaVersion:3,content:[{type:'futureNode',attrs:{payload:'不可丢弃'}}]} as any},
  pasteHtml(html:string){const transfer=new DataTransfer();transfer.setData('text/html',html);transfer.setData('text/plain','外部文字');window.document.querySelector('.composer-richtext')!.dispatchEvent(new ClipboardEvent('paste',{clipboardData:transfer,bubbles:true,cancelable:true}))},
  pasteFragment(payload:string,text='需求说明'){const transfer=new DataTransfer();transfer.setData('application/x-navora-composer-fragment',payload);transfer.setData('text/plain',text);window.document.querySelector('.composer-richtext')!.dispatchEvent(new ClipboardEvent('paste',{clipboardData:transfer,bubbles:true,cancelable:true}))},
  selectText(text:string){const root=window.document.querySelector<HTMLElement>('.composer-richtext')!;root.focus();const walk=window.document.createTreeWalker(root,NodeFilter.SHOW_TEXT);let node:Node|null;while(node=walk.nextNode()){const index=node.textContent?.indexOf(text)??-1;if(index<0)continue;const range=window.document.createRange();range.setStart(node,index);range.setEnd(node,index+text.length);const selected=window.getSelection()!;selected.removeAllRanges();selected.addRange(range);root.dispatchEvent(new Event('focus'));window.document.dispatchEvent(new Event('selectionchange'));return true}return false},
  insert(mode:'reference'|'excerpt',label='需求说明'){return field.value?.insertContext({id:crypto.randomUUID(),label,mode,status:'ready',source:{kind:'file',identity:'requirements.md',path:'requirements.md',chatId:'chat-a'}},mode==='excerpt'?'可编辑的摘录副本':'')},
}
</script>
<style>
:root{font-family:'Segoe UI','Microsoft YaHei UI',sans-serif;--navora-ink:#283e56;--navora-muted:#78899d;--navora-surface:#fff;--navora-stroke:#dce4ed;--navora-accent:#376d9f;--control-selected:#e8f0f8;--control-hover:#edf2f7;--appearance-well:#f6f8fb;--control-danger:#ad4239}
body{margin:0;background:#f2f5f9;color:var(--navora-ink)}main{margin:50px auto;max-width:850px;padding:0 16px}h1{font-size:20px;font-weight:600}main>p{font-size:13px;color:var(--navora-muted)}button{border:0;background:transparent;color:inherit;font:inherit;cursor:default}button:hover{background:var(--control-hover)}input,textarea{font:inherit;box-sizing:border-box}button:focus-visible{outline:2px solid var(--navora-accent);outline-offset:1px}.fixture-composer{margin-top:240px;border:1px solid #bfcfe1;border-radius:18px;background:#f8fafc;padding:16px}.fixture-composer footer{display:flex;align-items:center;gap:15px;margin-top:15px;color:var(--navora-muted);font-size:12px}.fixture-composer footer button{width:32px;height:32px;border-radius:6px;display:grid;place-items:center;font-size:20px}.fixture-composer .composer-document-editor{min-height:90px}
@media(max-width:500px){main{margin-top:16px}.fixture-composer{margin-top:190px;padding:12px}.fixture-composer footer span{font-size:10px}}
</style>
